exercise.solution:
def conv_geometry(size, layers):
    if size <= 0:
        raise ValueError("输入尺寸必须为正")
    receptive, jump = 1, 1
    for kernel, stride, padding, dilation in layers:
        if min(kernel, stride, dilation) <= 0 or padding < 0:
            raise ValueError("卷积参数无效")
        size = (size + 2*padding - dilation*(kernel-1) - 1)//stride + 1
        if size <= 0:
            raise ValueError("没有有效输出位置")
        receptive += (kernel-1)*dilation*jump
        jump *= stride
    return size, receptive, jump

