import math

def symmetric_pair_ce(scores):
    n = len(scores)
    if n == 0 or any(len(row) != n for row in scores):
        raise ValueError("需要非空方阵")
    def lse(values):
        m = max(values)
        return m + math.log(sum(math.exp(x-m) for x in values))
    row_loss = sum(lse(row)-row[i] for i, row in enumerate(scores))
    col_loss = 0.0
    for i in range(n):
        column = [scores[j][i] for j in range(n)]
        col_loss += lse(column)-scores[i][i]
    return (row_loss+col_loss)/(2*n)

