def next_token_example(ids, valid_length, prompt_length):
    if not 1 <= valid_length <= len(ids):
        raise ValueError("有效长度无效")
    if not 0 <= prompt_length <= valid_length:
        raise ValueError("prompt 长度无效")
    inputs = list(ids[:-1])
    attention = [i < valid_length for i in range(len(inputs))]
    targets = [ids[i] if prompt_length <= i < valid_length else -100
               for i in range(1, len(ids))]
    return {"input_ids":inputs, "attention_mask":attention, "targets":targets}

