def incremental_allowed(past_len, new_len):
    if past_len < 0 or new_len <= 0:
        raise ValueError("历史长度需非负，新长度需为正")
    return [[key <= past_len+query for key in range(past_len+new_len)]
            for query in range(new_len)]

