exercise.solution:
def film_batch(features, gamma, beta):
    if len(features) != len(gamma) or len(features) != len(beta):
        raise ValueError("Batch 大小不一致")
    result = []
    for batch,row_list in enumerate(features):
        if len(gamma[batch]) != len(beta[batch]):
            raise ValueError("条件通道不一致")
        rows = []
        for row in row_list:
            if len(row) != len(gamma[batch]):
                raise ValueError("特征通道不一致")
            rows.append([gamma[batch][d]*value+beta[batch][d]
                         for d,value in enumerate(row)])
        result.append(rows)
    return result
